CREATE TABLE eap_alert_rules (id UUID PRIMARY KEY,tenant_id UUID NOT NULL,rule_code VARCHAR(120) NOT NULL,rule_name VARCHAR(180) NOT NULL,metric_code VARCHAR(120) NOT NULL,operator VARCHAR(30) NOT NULL,threshold_value NUMERIC(30,8) NOT NULL,severity VARCHAR(20) NOT NULL,cooldown_seconds BIGINT NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL,created_by VARCHAR(160) NOT NULL,updated_at TIMESTAMPTZ NOT NULL,updated_by VARCHAR(160) NOT NULL,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT uq_eap_alert_rule_code UNIQUE(tenant_id,rule_code));
CREATE INDEX ix_eap_alert_metric ON eap_alert_rules(tenant_id,metric_code,active);
CREATE TABLE eap_alerts (id UUID PRIMARY KEY,tenant_id UUID NOT NULL,rule_id UUID NOT NULL REFERENCES eap_alert_rules(id),metric_code VARCHAR(120) NOT NULL,observed_value NUMERIC(30,8) NOT NULL,threshold_value NUMERIC(30,8) NOT NULL,severity VARCHAR(20) NOT NULL,alert_status VARCHAR(20) NOT NULL,triggered_at TIMESTAMPTZ NOT NULL,acknowledged_at TIMESTAMPTZ,resolved_at TIMESTAMPTZ,status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL,created_by VARCHAR(160) NOT NULL,updated_at TIMESTAMPTZ NOT NULL,updated_by VARCHAR(160) NOT NULL,version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX ix_eap_alert_status ON eap_alerts(tenant_id,alert_status,triggered_at);
CREATE TABLE eap_report_schedules (id UUID PRIMARY KEY,tenant_id UUID NOT NULL,schedule_code VARCHAR(120) NOT NULL,report_code VARCHAR(120) NOT NULL,cron_expression VARCHAR(120) NOT NULL,timezone VARCHAR(80) NOT NULL,schedule_status VARCHAR(20) NOT NULL,delivery_channel VARCHAR(20) NOT NULL,recipients_json TEXT NOT NULL,parameters_json TEXT,next_run_at TIMESTAMPTZ,last_run_at TIMESTAMPTZ,status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL,created_by VARCHAR(160) NOT NULL,updated_at TIMESTAMPTZ NOT NULL,updated_by VARCHAR(160) NOT NULL,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT uq_eap_schedule_code UNIQUE(tenant_id,schedule_code));
CREATE INDEX ix_eap_schedule_due ON eap_report_schedules(tenant_id,schedule_status,next_run_at);
CREATE TABLE eap_data_sources (id UUID PRIMARY KEY,tenant_id UUID NOT NULL,source_code VARCHAR(120) NOT NULL,source_name VARCHAR(180) NOT NULL,source_type VARCHAR(30) NOT NULL,source_service VARCHAR(100),configuration_reference VARCHAR(240),schema_json TEXT,active BOOLEAN NOT NULL DEFAULT TRUE,status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL,created_by VARCHAR(160) NOT NULL,updated_at TIMESTAMPTZ NOT NULL,updated_by VARCHAR(160) NOT NULL,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT uq_eap_data_source_code UNIQUE(tenant_id,source_code));
